from pathlib import Path
from urllib.request import Request,build_opener,ProxyHandler
CTX={"purchase_date":"2026-10-25","delivery_date":"2026-11-03","country":"US","category":"footwear"}
U=["Can a cobbler replace the heel caps?","Do you offer a multi-pair price?","Is the lining made from wool?","Are these okay for pickleball?","Can I order replacement laces?","How should I clean the leather?","Are they insulated for snow?","Do these run true to size?","Can I add a custom insole?","What is the shoe weight?","Do they have a composite toe?","Is there a warranty against wear?","Can I buy a matching belt?","Are these approved for airline crew uniforms?","Can the sole be resoled?"]
