CASES=[]
for i,q in enumerate(U,1): CASES.append({"id":f"u{i:02}","question":q,"group":"unsupported","topic":"unsupported","aspect":"none","status":"insufficient_evidence"})
for i,(q,t,a,s) in enumerate(S,1): CASES.append({"id":f"s{i:02}","question":q,"group":"supported","topic":t,"aspect":a,"status":s})
for i,q in enumerate(M,1): CASES.append({"id":f"m{i:02}","question":q,"group":"mixed","topic":"clarify","aspect":"none","status":"clarify"})
