def run(port):
 op=build_opener(ProxyHandler({}));out=[]
 for c in CASES:
  req=Request(f"http://127.0.0.1:{port}/api/answer",data=json.dumps({"question":c["question"],"context":CTX}).encode(),headers={"Content-Type":"application/json"},method="POST");st=time.monotonic()
  with op.open(req,timeout=60) as r:d=json.load(r)
  route=d.get("routing",{});out.append({"id":c["id"],"group":c["group"],"question":c["question"],"expected":{"topic":c["topic"],"aspect":c["aspect"],"status":c["status"]},"actual":{"topic":route.get("topic",route.get("status")),"aspect":route.get("aspect"),"status":d.get("status")},"passed":route.get("topic")==c["topic"] and route.get("aspect")==c["aspect"] and d.get("status")==c["status"],"answer":d.get("answer"),"seconds":round(time.monotonic()-st,3)})
 groups={g:[r for r in out if r["group"]==g] for g in ("unsupported","supported","mixed","ambiguous")}; nonclar=[r for r in groups["supported"] if r["expected"]["status"]!="clarify"]
 return {"kind":"second frozen 50-case local evaluation","limitations":"Single developer-authored evaluation run with local small model; not proof of production reliability.","cases":len(out),"all_passed":sum(r["passed"] for r in out),"unsupported_false_accepts":sum(r["actual"]["topic"]=="return_policy" for r in groups["unsupported"]),"mixed_answered":sum(r["actual"]["status"]=="answered" for r in groups["mixed"]),"supported_correct":sum(r["passed"] for r in groups["supported"]),"supported_total":len(groups["supported"]),"unnecessary_clarifications":sum(r["actual"]["status"]=="clarify" for r in nonclar),"supported_without_expected_clarify":len(nonclar),"results":out}
if __name__=="__main__":
 p=argparse.ArgumentParser();p.add_argument("--port",type=int,required=True);p.add_argument("--output",default="blind-results.json");a=p.parse_args();d=run(a.port);Path(a.output).write_text(json.dumps(d,indent=2)+"\n");print(json.dumps({k:v for k,v in d.items() if k!="results"},indent=2))
